import {communityRequest} from './panels.js';
async function assist(kind,extra={}){await window.joinSharedActivity();return communityRequest('assist',{kind,...extra});}
window.explainQuiz=async(id,container)=>{let output=container.querySelector('.quiz-more');if(!output){output=document.createElement('p');output.className='quiz-more';container.append(output);}output.textContent='해설 확인 중…';try{const result=await assist('quiz',{questionId:id});output.textContent=result.text+(result.mode==='fallback'?' · 검증된 기본 해설':'');}catch(error){output.textContent=error.message;}};
const wishForm=document.querySelector('#wish-form'),recommend=document.createElement('button');recommend.type='button';recommend.textContent='장식 추천';const notice=document.createElement('small');notice.className='ai-notice';notice.textContent='장식 추천을 누르면 소원 내용이 OpenAI로 전송됩니다.';wishForm.append(notice);wishForm.querySelector('button[type=submit]').before(recommend);recommend.onclick=async()=>{const output=wishForm.querySelector('output[role=status]'),text=wishForm.elements.message.value.trim();if(!text){output.textContent='소원을 먼저 입력해 주세요.';return;}recommend.disabled=true;try{const result=await assist('wish',{text});output.textContent=result.text+(result.mode==='fallback'?' · 기본 추천':'');window.dispatchEvent(new CustomEvent('lab:decoration-choice',{detail:result}));}catch(error){output.textContent=error.message;}finally{recommend.disabled=false;}};
const eventButton=document.createElement('button');eventButton.id='world-event';eventButton.hidden=true;document.body.append(eventButton);let active=null;eventButton.onclick=()=>active?.kind==='quiz'?window.openQuickQuiz?.():window.travelToPlace?.('tree');
async function events(){if(!window.labSocialJoined||document.hidden)return;try{const {events:items}=await communityRequest('events'),now=Date.now();active=items.find(e=>e.startsAt<=now&&e.endsAt>now)||null;const time=new Date(now+9*3600000),hour=time.getUTCHours();if(!active&&hour>=18&&hour<24&&time.getUTCMinutes()<2)active={kind:'lights',title:'트리 라이트 쇼'};window.labLiveEvent=active;eventButton.hidden=!active;if(active)eventButton.textContent=active.title;}catch{}}
window.addEventListener('lab:access',events);setInterval(events,30000);events();
